import test from 'node:test';import assert from 'node:assert/strict';
import {initialState,applyEvent,finalizeTurn} from '../engine.js';
function npc(s,name,ref,kind='merchant'){applyEvent(s,{type:'spawn',name,ref,kind,appearance:{beard:'long'}});return s.npcs.at(-1).id;}
test('novo encontro na mesma floresta e com mesmo nome remove o NPC anterior',()=>{const s=initialState();applyEvent(s,{type:'scene',scene:'forest',location:'Floresta'});const old=npc(s,'Borin','borin');applyEvent(s,{type:'talk',target:old,message:'Adeus'});const turn=finalizeTurn({narration:'Você deixa Borin para trás e encontra um goblin.',visibleNpcs:['grik'],events:[{type:'scene',scene:'forest',location:'Floresta'},{type:'spawn',name:'Grik',ref:'grik',kind:'goblin'}]});for(const e of turn.events)applyEvent(s,e);assert.deepEqual(s.npcs.map(n=>n.name),['Grik']);assert.ok(!s.npcs.some(n=>n.id===old));assert.equal(s.dialogue,null);assert.equal(s.selected,s.npcs[0].id);assert.equal(s.encounter,2);});
test('snapshot reconcilia presença mesmo sem troca de ambiente e limpa seleção/fala antigas',()=>{const s=initialState(),old=npc(s,'Borin','borin');npc(s,'Grik','grik','goblin');applyEvent(s,{type:'talk',target:old,speaker:old,message:'Bom caminho!'});applyEvent(s,{type:'cast',targets:['grik']});assert.deepEqual(s.npcs.map(n=>n.ref),['grik']);assert.equal(s.dialogue,null);assert.equal(s.selected,s.npcs[0].id);const id=s.npcs[0].id;for(const e of finalizeTurn({narration:'Borin fica na lembrança. Grik observa você.',visibleNpcs:[id],events:[]}).events)applyEvent(s,e);assert.equal(s.npcs[0].id,id);applyEvent(s,{type:'cast',targets:[]});assert.equal(s.npcs.length,0);assert.equal(s.selected,null);});
test('somente acompanhantes explícitos atravessam a viagem sem perder identidade',()=>{const s=initialState();npc(s,'Borin','borin');const ally=npc(s,'Aliado','ally','guard'),appearance=structuredClone(s.npcs[1].appearance);applyEvent(s,{type:'scene',scene:'forest',carry:['ally']});assert.equal(s.npcs.length,1);assert.equal(s.npcs[0].id,ally);assert.deepEqual(s.npcs[0].appearance,appearance);applyEvent(s,{type:'move',target:ally});assert.equal(s.npcs.length,1);});
test('presença ausente, duplicada ou com referência inexistente é rejeitada',()=>{assert.throws(()=>finalizeTurn({narration:'Teste',events:[]}));assert.throws(()=>finalizeTurn({narration:'Teste',events:[],visibleNpcs:['x','x']}));const s=initialState();npc(s,'Borin','borin');const before=structuredClone(s);assert.throws(()=>applyEvent(s,{type:'cast',targets:['missing']}));assert.deepEqual(s,before);assert.throws(()=>applyEvent(s,{type:'scene',scene:'forest',carry:['missing']}));assert.deepEqual(s,before);});
